function climbWays(n: number, memo = new Map<number, number>()): number {
  if (n <= 1) return 1
  if (memo.has(n)) return memo.get(n)!
  const ways = climbWays(n - 1, memo) + climbWays(n - 2, memo)
  memo.set(n, ways)
  return ways
}

