def climb_ways(n, memo=None):
    if memo is None:
        memo = {}
    if n <= 1:
        return 1
    if n in memo:
        return memo[n]
    memo[n] = climb_ways(n - 1, memo) + climb_ways(n - 2, memo)
    return memo[n]
